import{az as r,M as n}from"./index-B3nQBTv3.js";class a{static async fetchStatus(s=!1){const e=await r.get("/cm-analysis/status");return e.type==="error"?(s||r.showGenericError(e,"CM 解析の状態を取得できませんでした。"),null):e.data}static async updateSettings(s){const e=await r.put("/cm-analysis/settings",s);return e.type==="error"?(r.showGenericError(e,"CM 解析設定を更新できませんでした。"),null):e.data}static async downloadModel(){const s=await r.post("/cm-analysis/model/download");return s.type==="error"?(r.showGenericError(s,"CM 検出モデルのダウンロードを開始できませんでした。"),!1):!0}static async fetchJobs(s=!1){const e=await r.get("/cm-analysis/jobs");return e.type==="error"?(s||r.showGenericError(e,"CM 解析ジョブの一覧を取得できませんでした。"),null):e.data.jobs}static async enqueue(s){const e=await r.post("/cm-analysis/jobs",{video_ids:s});return e.type==="error"?(e.status===400?r.showGenericError(e,"CM 解析を開始できませんでした。設定の「CM 解析設定」で機能を有効にし、モデルを準備してください。"):e.status===403?r.showGenericError(e,"CM 解析の実行には管理者権限が必要です。"):r.showGenericError(e,"CM 解析を開始できませんでした。"),null):e.data}static async countAnalyzedWithCurrentVersion(s){const e=await a.fetchStatus(!0);if(e===null)return{count:0,label:""};const t=`AI ${e.model_version}`;return{count:s.filter(o=>o===t).length,label:t}}static async requestAnalysis(s){const e=await a.enqueue(s);e!==null&&(e===0?n.show("選択した録画番組は、すでに CM 解析の順番待ち (または解析中) です。"):n.success(`${e} 件の録画番組を CM 解析の順番待ちに追加しました。
進行状況は、設定の「CM 解析設定」で確認できます。`))}static async cancel(s,e=!1){const t=await r.delete("/cm-analysis/jobs",{params:{video_id:s,clear_finished:e}});return t.type==="error"?(r.showGenericError(t,"CM 解析ジョブを取り消せませんでした。"),!1):!0}}export{a as C};
